@FunctionalInterface
interface PriceModifier {
    // The single abstract method
    double apply(double basePrice);

    // Default helper method (does NOT violate SAM count!)
    default void printDiscounted(double price) {
        System.out.println("Original: $" + price + " | Final: $" + String.format("%.2f", apply(price)));
    }
}

// Traditional OOP implementation via concrete class
class StudentDiscount implements PriceModifier {
    @Override
    public double apply(double basePrice) {
        return basePrice * 0.85; // 15% off
    }
}

public class FunctionalDemo {
    public static void main(String[] args) {
        PriceModifier student = new StudentDiscount();
        student.printDiscounted(100.0);

        // Preview: Can also be passed as a lambda expression!
        PriceModifier vip = (price) -> price * 0.70; // 30% off
        vip.printDiscounted(100.0);
    }
}

