@FunctionalInterface
interface TextFilter {
    boolean accept(String text);
}

class FilterProcessor {
    public static void filterAndPrint(String[] list, TextFilter filter) {
        for (String item : list) {
            if (filter.accept(item)) {
                System.out.println("MATCH: " + item);
            }
        }
    }
}

public class FilterApp {
    public static void main(String[] args) {
        String[] files = { "doc.txt", "pic.jpg", "data.csv", "notes.txt" };

        // Filter for text files using a lambda!
        FilterProcessor.filterAndPrint(files, (f) -> f.endsWith(".txt"));
    }
}

