@FunctionalInterface
interface BinaryMathOp {
    int calculate(int a, int b);
}

class AdditionOp implements BinaryMathOp {
    @Override
    public int calculate(int a, int b) {
        return a + b;
    }
}

public class MathApp {
    public static void main(String[] args) {
        BinaryMathOp op = new AdditionOp();
        int sum = op.calculate(15, 25);
        System.out.println("Sum: " + sum);
    }
}

@FunctionalInterface
interface StringModifier {
    String modify(String s);
    default void printModified(String s) {
        System.out.println("Result: " + modify(s));
    }
}

class BracketModifier implements StringModifier {
    @Override
    public String modify(String s) {
        return "[" + s + "]";
    }
}

public class ModifierApp {
    public static void main(String[] args) {
        StringModifier m1 = new BracketModifier();
        m1.printModified("JAVA-OOP");

        StringModifier shouting = (s) -> s.toUpperCase() + "!!!";
        shouting.printModified("hello");
    }
}

@FunctionalInterface
interface NumberCondition {
    boolean check(int n);
}

class NumberFilter {
    public static void filterAndPrint(int[] nums, NumberCondition condition) {
        for (int n : nums) {
            if (condition.check(n)) {
                System.out.println(n);
            }
        }
    }
}

public class FilterApp {
    public static void main(String[] args) {
        int[] numbers = new int[] { 3, 10, 15, 22, 35, 40 };
        NumberFilter.filterAndPrint(numbers, (n) -> n % 2 == 0);
    }
}

